"""Publica o relatório legível a partir das decisões editoriais já registradas."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
r=json.loads((ROOT/'research/editorial-review.json').read_text(encoding='utf-8'))
course=json.loads((ROOT/'research/course-content.json').read_text(encoding='utf-8'))
lessons={l['slug']:l for l in course['lessons']}
def location(slug,step):
    if slug=='@introducao':return 'Introdução e arquitetura'
    l=lessons[slug]
    return f"Módulo {l['module']} · {l['title']} · passo {step}"
lines=['# Revisão de pertinência · v1.3.1','','A revisão confrontou os **427 passos das 98 aulas**, os **336 usos de imagens** da versão preparada v1.3.0 e as **338 fichas** da biblioteca. O catálogo de 83 operações permanece vinculado ao contrato OpenAPI. A conferência é editorial: não houve execução dos fluxos no Leapwork.','','**Resultado:** 12 usos de imagem removidos, sete capturas substituídas e três reposicionadas. Permanecem 324 usos de imagem no caderno, incluindo a introdução. Das inclusões da varredura, 73 permanecem após a revisão, usando 64 arquivos distintos. São 315 passos ilustrados e 112 sem imagem.','','## Critérios','']
lines+=['- '+v for v in r['criteria']]
lines+=['','Os 83 passos que tiveram alteração incluem legendas e metadados de proveniência; isso não significa 83 erros factuais. O registro JSON mantém a versão exata revisada de cada aula, passo, ficha e imagem.','','## Imagens removidas','']
for d in r['supplementDecisions']:
    if d['action']=='remove':lines.append('- **'+location(d['lesson'],d['step'])+'**: '+d['reason'])
reasons={'dados-http':'A captura mostrava Method = POST, enquanto o exercício instrui uma chamada GET.','dados-textos':'A captura mostrava Substring, enquanto o passo instrui Trim.','controle-historico':'O canvas do fluxo não mostrava Version History; foi retirado e substituído, nesse passo, pela tabela já selecionada para a aula.','controle-restauracao':'A tabela de versões não mostrava as opções Only Flow, Full Restore e Full Copy comparadas no texto.'}
for d in r['removedOriginalFigures']:lines.append('- **'+location(d['lesson'],d['step'])+'**: '+reasons[d['lesson']])
lines+=['','## Capturas substituídas','']
for d in r['supplementDecisions']:
    if d['action']=='replace':lines.append('- **'+location(d['lesson'],d['step'])+'**: '+d['reason'])
for d in r['replacedOriginalFigures']:lines.append('- **'+location(d['lesson'],d['step'])+'**: '+d['reason'])
lines+=['','## Capturas reposicionadas','']
for d in r['supplementDecisions']:
    if d['action']=='move':lines.append('- **'+location(d['lesson'],d['step'])+' → passo '+str(d['targetStep'])+'**: '+d['reason'])
lines+=['','## Informações e fontes corrigidas','','- **Módulo 4 · Identificar o Controller · passo 4:** o link principal passou de License Management para User Management. A observação agora trata conta, Controller e papel. Refresh License saiu do passo. [Fonte](https://docs.leapwork.com/leapwork-flow/latest/administration/user-management).','- **Módulo 4 · Identificar o Controller · passo 1:** o texto passou a distinguir a seleção de Controller na entrada e Controller Settings. A captura mostra Select Controller. [Fonte](https://docs.leapwork.com/leapwork-flow/latest/administration/controller-settings).','- **Módulo 4 · Organizar usuários · passo 4:** User Management passou a ser o link principal para as opções de identidade; as fontes específicas continuam nas figuras e referências. [Fonte](https://docs.leapwork.com/leapwork-flow/latest/administration/user-management).','- **Módulo 3 · C# · conceitos e passo 3:** .NET 8 foi delimitado ao contexto 2026.1 da referência, com menção à migração .NET 10 anunciada nas notas 2026.3. Foi acrescentada a fonte da versão. [C# Code](https://docs.leapwork.com/leapwork-flow/latest/building-blocks/logic/c-sharp-code), [notas 2026.3](https://docs.leapwork.com/leapwork-flow/latest/release-notes/leapwork-flow-major-release-2026-3).','- **Biblioteca · Save File:** retirado o destino configurável sugerido pelo resumo; o texto agora descreve armazenamento gerenciado, nome automático e ausência de caminho manual. A aula já descrevia esse comportamento. [Fonte](https://docs.leapwork.com/leapwork-flow/latest/building-blocks/data-driven/save-file).','- **Biblioteca · Generate date/time:** o resumo agora declara que o bloco fornece o instante atual do sistema; uma base fixa exige outra entrada. [Fonte](https://docs.leapwork.com/leapwork-flow/latest/building-blocks/generators/generate-date-time).','- **Biblioteca · Navigate Web:** o resumo passou a abranger Navigation mode, incluindo histórico, atualização e nova aba, além de URL. [Fonte](https://docs.leapwork.com/leapwork-flow/latest/building-blocks/web/navigate-web).','- **Módulo 5 · Azure DevOps · passo 2:** o texto passou a começar pelo menu Import → Import from ADO que aparece na captura, antes da escolha de projeto e Area Path. [Fonte](https://docs.leapwork.com/leapwork-flow/latest/working-with-leapwork/microsoft-ado-test-plan-integration).','- **Legendas:** passaram a nomear o conteúdo visível e sua limitação: uma execução isolada não mostra todas as tentativas; a cópia na árvore não exibe seus agendamentos; Never selecionado não demonstra exigência de comentário. As fontes continuam ligadas a cada figura.','','## Verificação e limites','','- As suítes de navegador conferem imagens, rotas, notas, filtros, laboratórios e funcionamento offline.','- `scripts/check_editorial_review.py` confere a integridade da versão revisada e as regressões conhecidas. Ele não decide automaticamente se uma imagem é pertinente.','- `research/illustration-selection.json` exige seleção explícita e justificativa por figura. A coleta de um artigo não autoriza inserir todas as suas imagens.','- `research/editorial-review.json` registra as decisões e os hashes da versão revisada. Mudanças posteriores exigem nova conferência.','- [ENRIQUECIMENTO.md](ENRIQUECIMENTO.md) localiza as inclusões que permanecem no caderno.','']
(ROOT/'REVISAO.md').write_text('\n'.join(lines),encoding='utf-8')
print('REVISAO.md atualizado')
